{
  "modelPrompt": {
    "subject_definitions": "<Subject 1> golden coin with cat face emblem, appearance from <Picture 1>\n<Video 1> source video of spinning coin on green screen",
    "summary": "[video editing + reference generation] The target video is an edited version of <Video 1>. The original owl-faced coin is replaced throughout by <Subject 1> while preserving the exact spinning motion, trajectory, camera framing, green screen background and timing.",
    "retention_analysis": "<Video 1>: partially_preserved - spinning motion, rotation trajectory, camera position and green screen background retained; original coin design replaced by <Subject 1>\n<Subject 1>: attribute_transfer - cat face emblem applied to the coin in <Video 1>",
    "detailed_description": "Retain the reference appearance of the spinning coin. [Shot 1] A golden coin with a cat face emblem spins and flips in the center of a green screen background, following the exact motion path from the source video, starting face-on, rotating to show edge at 1.500s, and returning to face-on by 3.000s.",
    "overall_soundscape": "Silent with no diegetic sounds.",
    "non_diegetic_music": "None."
  },
  "displayPrompt": {
    "subject_definitions": "<Subject 1> 带有猫脸浮雕的金币，外观来自 <Picture 1>\n<Video 1> 绿幕上旋转硬币的源视频",
    "summary": "[video editing + reference generation] 目标视频是 <Video 1> 的编辑版本。原猫头鹰脸硬币在整个过程中被 <Subject 1> 替换，同时保留精确的旋转运动、轨迹、摄像机取景、绿幕背景和时序。",
    "retention_analysis": "<Video 1>: partially_preserved - 旋转运动、旋转轨迹、摄像机位置和绿幕背景保留；原硬币设计被 <Subject 1> 替换\n<Subject 1>: attribute_transfer - 猫脸浮雕应用于 <Video 1> 中的硬币",
    "detailed_description": "保留旋转硬币的参考外观。[Shot 1] 一枚带有猫脸浮雕的金币在绿幕背景中央旋转翻转，遵循源视频的精确运动路径，从正面开始，在1.500s时旋转至侧面边缘，并在3.000s时回到正面。",
    "overall_soundscape": "无声，无任何拟音效果。",
    "non_diegetic_music": "无。"
  }
}
